import { createFileRoute } from '@tanstack/react-router'
import { z } from 'zod'
import { InvoiceHistoryPage } from '@/features/transaction-history'

// @ts-ignore - Route will be generated by TanStack Router plugin
export const Route = createFileRoute('/_authenticated/invoice-history/')({
  // ?tab=history opens the invoice-wise / item-wise tab (default: the management list).
  // ?viewId=… opens that record's view over the page (the rate-history box's "new tab" link).
  validateSearch: z.object({ tab: z.enum(['list', 'history']).optional(), viewId: z.string().optional() }),
  component: InvoiceHistoryPage,
})
